Looking at the examples, I identified this rule:

1. **Top row** contains color markers at certain columns (a stamp pattern)
2. **Left column** contains direction markers: `3` = shift left by 1, `2` = shift right by 1
3. For each row with a left marker, the shape cells shift by ±1, and the top-row color pattern (also shifted by the same amount) overwrites any shape cells at those positions
4. Rows without left markers keep their shape cells unchanged
5. All markers are removed from the output

```python
def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    top_markers = {}
    for c in range(cols):
        if grid[0][c] != 0:
            top_markers[c] = grid[0][c]

    left_markers = {}
    for r in range(rows):
        if grid[r][0] != 0:
            left_markers[r] = grid[r][0]

    from collections import Counter
    color_counts = Counter()
    for r in range(1, rows):
        for c in range(1, cols):
            if grid[r][c] != 0:
                color_counts[grid[r][c]] += 1
    shape_color = color_counts.most_common(1)[0][0]

    out = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        if r in left_markers:
            val = left_markers[r]
            shift = -1 if val == 3 else 1 if val == 2 else 0

            shifted_top = {c + shift: v for c, v in top_markers.items()}

            for c in range(cols):
                if grid[r][c] == shape_color:
                    nc = c + shift
                    if 0 <= nc < cols:
                        if nc in shifted_top:
                            out[r][nc] = shifted_top[nc]
                        else:
                            out[r][nc] = shape_color
        else:
            for c in range(cols):
                if grid[r][c] == shape_color:
                    out[r][c] = shape_color

    return out
